39	func Execute(version string, args []string) error {
40		// Translate SIGINT/SIGTERM into context cancellation. Every Git subprocess
41		// is built with exec.CommandContext, so cancellation kills it; without this
42		// the default signal action ends only this process and leaves a running
43		// `git grep` child orphaned and burning CPU. After the first signal the
44		// default action is restored, so a second one still terminates at once.
45		// SIGKILL cannot be intercepted, and macOS has no parent-death signal, so a
46		// SIGKILLed parent still orphans its children until they next write to the
47		// closed stdout pipe (SIGPIPE).
48		ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
49		defer stop()
50		go func() {
51			<-ctx.Done()
52			stop()
53		}()
54		return Run(ctx, Options{
55			Version: version,
56			Env:     EnvFromOS(),
57			Stdout:  os.Stdout,
58			Stderr:  os.Stderr,
59			Stdin:   os.Stdin,
60		}, args)
61	}
