80		// view and exits, without touching each runX. Only fires for commands that
81		// have a doc entry — which includes `help` itself, so `help --help` prints
82		// help's own detail view rather than the root listing. A bare `--help` has
83		// no command word and is handled above.
84		if doc, ok := findCommandDoc(args[0]); ok && wantsHelp(doc, args[1:]) {
85			renderCommandHelp(opts.Stdout, args[0])
