161		asJSON := false
162		var asserts []string
163		for index := 0; index < len(args); index++ {
164			switch args[index] {
165			case "--json":
166				asJSON = true
167			case "--assert":
168				// Repeatable: a harness usually drives more than one verb, and finding out about the
169				// second one only after the first has been fixed costs another whole run.
170				if index+1 >= len(args) {
171					return errors.New("doctor --assert needs a command line, for example --assert \"search --profile full\"")
172				}
173				index++
174				asserts = append(asserts, args[index])
175			default:
176				return errors.New("doctor accepts only --json and --assert \"<command line>\"")
177			}
178		}
179		// The assertions run FIRST and stop the report: a caller that asked whether this binary can
180		// serve its command line wants that answer, and printing an otherwise-healthy environment
181		// report above the failure buries it.
182		for _, spec := range asserts {
183			if err := checkPreflight(opts.Version, spec); err != nil {
184				return err
185			}
186		}
187		if len(asserts) > 0 && !asJSON {
188			for _, spec := range asserts {
189				fmt.Fprintf(opts.Stdout, "assert_ok=%q\n", spec)
190			}
191		}
