232				return fmt.Errorf("close plugin data probe: %w", err)
233			}
234			if err := os.Remove(probeName); err != nil {
235				return fmt.Errorf("remove plugin data probe: %w", err)
236			}
237			report["plugin_data_dir"] = "writable"
238			if !asJSON {
239				fmt.Fprintln(opts.Stdout, "plugin_data_dir=writable")
240			}
241		}
242	
243		repo, err := resolveRepo(ctx, opts.Env, "")
244		if err == nil {
245			// Snapshot construction converts the resolved repository to an absolute,
246			// cleaned path before deriving either RepoRoot or RepoKey. Doctor is the
247			// preflight for that snapshot, so advertise the same spelling rather than
248			// the caller's possibly-relative ENTIRE_REPO_ROOT value.
249			repo, err = filepath.Abs(repo)
