251		if err != nil {
252			report["repo_root"] = ""
253			report["repo_error"] = err.Error()
254			if asJSON {
255				return json.NewEncoder(termsafe.NewJSONWriter(opts.Stdout)).Encode(report)
256			}
257			fmt.Fprintf(opts.Stdout, "repo_root=%s\n", valueOrUnset(""))
258			fmt.Fprintf(opts.Stdout, "repo_error=%s\n", err)
259			return nil
