464					if ok {
465						// Same wrap as the unfiltered hit below: escaping is idempotent, and an
466						// entry written before the C1 rule must not reach the terminal raw.
467						if _, err := termsafe.NewJSONWriter(opts.Stdout).Write(filtered); err != nil {
468							return err
469						}
470						warnIfPartial(opts.Stderr, flags.Worktree, cachedSummary)
471						reportMatched(matched)
472						return nil
473					}
474				}
475			}
476			// On a miss, the unfiltered edges stream is teed into the cache entry while
477			// only the matching relations reach stdout, so the next targeted query on
478			// this tree, whatever it asks, is a hit.
479			var cacheRecord func(any) error
480			if spool = beginRecordsSpool(recordsCache, opts.Stderr); spool != nil {
481				cacheRecord = newRecordEncoder(spool)
482			}
483			var matched int
484			if err := sem.StreamSnapshot(ctx, repo, opts.Version, options, func(record any) error {
485				capture(record)
486				if cacheRecord != nil && includeRecord("edges", record) {
487					if err := cacheRecord(record); err != nil {
488						return err
489					}
490				}
491				switch r := record.(type) {
492				case sem.RelationRecord:
493					if !relationMatches(r, flags) {
494						return nil
495					}
496					matched++
497					return encodeRecord(r)
498				case sem.FileRecord, sem.ExternalRecord, sem.SymbolRecord:
499					return nil // suppressed for a targeted edge query
500				default: // header, summary
501					return encodeRecord(record)
502				}
503			}); err != nil {
504				return err
505			}
506			warnIfPartial(opts.Stderr, flags.Worktree, summary)
507			reportMatched(matched)
508			if spool != nil {
509				// Best effort: a failed cache write never fails the command, but it is
510				// said once on stderr rather than silently costing a re-parse per run.
511				if err := recordsCache.Store(spool, summary, snapshotHeader); err != nil {
512					fmt.Fprintf(opts.Stderr, "graph: provider records cache not stored: %v\n", err)
513				}
514				spool = nil
515			}
516			return nil
517		}
518	
519		if recordsCache != nil {
520			if records, cachedSummary, hit := recordsCache.Load(); hit {
521				// Replayed bytes need the same wrap the encoder below gets. This path does
522				// not go through encodeRecord at all, so a cache entry written before the
523				// C1 rule existed — or by any build that predates it — would stream the
524				// repository's raw control straight to the terminal on every hit. Escaping
525				// is idempotent, so a clean entry passes through unchanged.
526				if _, err := termsafe.NewJSONWriter(opts.Stdout).Write(records); err != nil {
527					return err
528				}
529				warnIfPartial(opts.Stderr, flags.Worktree, cachedSummary)
530				return nil
531			}
532		}
533	
534		// On a miss, tee the serialized record stream into the disk spool so we can
535		// persist it after a successful run without a second pass over the graph.
536		// The spool gzips to a temporary file in the cache directory, so the tee's
537		// memory stays constant whatever the graph's size: the cache is on by
538		// default, and an in-memory capture here once held the command's ENTIRE
539		// output — or, capped, silently stored nothing on exactly the large
540		// repositories the cache matters most for.
541		if spool = beginRecordsSpool(recordsCache, opts.Stderr); spool != nil {
542			encodeRecord = newRecordEncoder(io.MultiWriter(opts.Stdout, spool))
543		}
544		if err := sem.StreamSnapshot(ctx, repo, opts.Version, options, func(record any) error {
545			capture(record)
546			if !includeRecord(mode, record) {
547				return nil
548			}
549			return encodeRecord(record)
550		}); err != nil {
551			return err
552		}
553		if scipEncoder != nil {
554			if err := writeSCIPOmissionNote(opts.Stderr, scipOmissionNoteWithSummary(scipEncoder.OmissionNote(), summary)); err != nil {
555				return err
556			}
557		} else {
558			warnIfPartial(opts.Stderr, flags.Worktree, summary)
559		}
560		if spool != nil {
561			// Best effort: a failed cache write never fails the command, but it is
562			// said once on stderr rather than silently costing a re-parse per run.
563			if err := recordsCache.Store(spool, summary, snapshotHeader); err != nil {
564				fmt.Fprintf(opts.Stderr, "graph: provider records cache not stored: %v\n", err)
565			}
566			spool = nil
567		}
568		return nil
569	}
570	
571	// beginRecordsSpool opens the disk spool a cold run tees its records into, or
572	// returns nil (after one stderr line) when the cache cannot take them. The
573	// spool writes ALWAYS report success to the io.MultiWriter that also feeds
574	// stdout only in the sense that a working spool never short-writes; a spool
575	// that cannot even open is dropped here so no cache failure can abort the
576	// stream the command exists to produce. Its predecessor buffered the capture
577	// in memory under a 64MB cap and silently stored nothing past it, so every
578	// repository whose snapshot outgrew the cap re-parsed on each run.
579	func beginRecordsSpool(recordsCache *sem.ProviderRecordsCacheTransaction, stderr io.Writer) *sem.ProviderRecordsSpool {
580		spool, err := recordsCache.NewSpool()
581		if err != nil {
582			fmt.Fprintf(stderr, "graph: provider records cache unavailable: %v\n", err)
583			return nil
584		}
585		return spool
586	}
