588	func scipOmissionNoteWithSummary(note sem.SCIPOmissionNote, summary *sem.SnapshotSummary) sem.SCIPOmissionNote {
589		if summary == nil {
590			return note
591		}
592		note.WarningCount = len(summary.Warnings)
593		note.PartialFailureCount = len(summary.PartialFailures)
594		// The records themselves, not just how many. SCIP cannot represent a file
595		// that was discovered but not parsed, so without these the note is the only
596		// place that information could have survived, and it was being reduced to an
597		// integer.
598		note.PartialFailures = summary.PartialFailures
599		// Which languages were only inventoried, so a consumer can scope trust per
600		// language the way the feed contract expects.
601		note.LanguageTiers = summary.LanguageTiers
602		level := summary.Stats.CompletenessLevel
603		if level == "" || level == "ok" {
604			return note
605		}
606		note.PartialSnapshot = true
607		note.CompletenessLevel = level
608		return note
609	}
610	
611	func writeSCIPOmissionNote(w io.Writer, note sem.SCIPOmissionNote) error {
612		// The note is the one TEXT stream `--format scip` writes, and it is written to
613		// a terminal. It is wrapped for the same structural reason every other machine
614		// encoder here is: a sink left unwrapped is the one the next field added to
615		// this record forgets about.
616		encoder := json.NewEncoder(termsafe.NewJSONWriter(w))
617		encoder.SetEscapeHTML(false)
618		return encoder.Encode(note)
619	}
