621	// warnIfPartial prints a loud stderr banner when the snapshot did not fully cover
622	// the repository, so a silent partial parse (the #1 sharp edge: running in a
623	// mis-scoped subdir without --worktree, which indexes only a stray config file
624	// and reports "ok") becomes impossible to miss. Silent on a clean "ok" run.
625	func warnIfPartial(w io.Writer, worktree bool, s *sem.SnapshotSummary) {
626		if s == nil {
627			return
628		}
629		level := s.Stats.CompletenessLevel
630		if level == "" || level == "ok" {
631			return
632		}
633		fmt.Fprintf(w, "\n⚠️  graph is %s: parsed %d/%d files, %d symbols, %d relations (languages: %s).\n",
634			strings.ToUpper(level), s.Stats.ParsedFiles, s.Stats.Files, s.Stats.Symbols,
635			s.Stats.Relations, strings.Join(s.Languages, ", "))
636		switch {
637		case s.Stats.Files <= 2 && !worktree:
638			fmt.Fprintf(w, "   Only %d file(s) were discovered — you may be indexing a subdirectory or an\n"+
639				"   unexpected commit. Run from the repo root, or pass --worktree to index the\n"+
640				"   working tree instead of HEAD.\n", s.Stats.Files)
641		case s.Stats.ParsedFiles*2 < s.Stats.Files:
642			fmt.Fprintf(w, "   Over half the discovered files were not parsed (unsupported language or\n"+
643				"   parse errors). Graph queries will miss code in those files.\n")
644		default:
645			fmt.Fprintf(w, "   The graph is incomplete; treat query results as partial.\n")
646		}
647	}
