649	// filterCachedEdgeRecords applies a targeted edge query to a cached `edges`
650	// stream, which holds only the header, relations and summary (includeRecord):
651	// relation lines pass when they match and everything else passes, exactly as
652	// the uncached targeted stream decides. Lines are passed through as stored, so a
653	// hit is byte-identical to the miss that wrote it. A line that does not decode reports !ok, and the caller
654	// rebuilds rather than trusting an entry it cannot read.
655	func filterCachedEdgeRecords(records []byte, flags providerFlags) ([]byte, int, bool) {
656		var filtered bytes.Buffer
657		matched := 0
658		for len(records) > 0 {
659			line := records
660			if index := bytes.IndexByte(records, '\n'); index >= 0 {
661				line, records = records[:index+1], records[index+1:]
662			} else {
663				records = nil
664			}
665			if len(bytes.TrimSpace(line)) == 0 {
666				continue
667			}
668			var kind sem.ProviderRecord
669			if err := json.Unmarshal(line, &kind); err != nil {
670				return nil, 0, false
671			}
672			if kind.RecordType == "relation" {
673				var relation sem.RelationRecord
674				if err := json.Unmarshal(line, &relation); err != nil {
675					return nil, 0, false
676				}
677				if !relationMatches(relation, flags) {
678					continue
679				}
680				matched++
681			}
682			filtered.Write(line)
683		}
684		return filtered.Bytes(), matched, true
685	}
