687	// includeRecord filters streamed records for the symbols and edges modes, which
688	// emit a subset of the full snapshot.
689	func includeRecord(mode string, record any) bool {
690		switch record.(type) {
691		case sem.FileRecord, sem.ExternalRecord:
692			return mode == "snapshot"
693		case sem.SymbolRecord:
694			return mode == "snapshot" || mode == "symbols"
695		case sem.RelationRecord:
696			return mode == "snapshot" || mode == "edges"
697		default: // header, summary
698			return true
699		}
700	}
