719	type providerFlags struct {
720		Repo         string
721		Format       string
722		Profile      string
723		NoNetwork    bool
724		Worktree     bool
725		Progress     bool
726		IgnoreFiles  []string
727		IncludeFiles []string
728		// Targeted edge filters (edges mode). When any is set the command emits only
729		// the matching relation records (plus header/summary) instead of the whole
730		// graph, so "callers of X" is a tiny reply rather than a 50MB dump that the
731		// caller then greps client-side. --to/--from match a symbol by full stable ID
732		// or by trailing name segment (IDs are `...:kind:name`); --relation is one or
733		// more edge types (comma-separated, case-insensitive), e.g. CALLS,REFERENCES.
734		To       string
735		From     string
736		Relation []string
737		// CacheDir/DisableCache control the committed-record cache. Empty CacheDir
738		// falls back to ENTIRE_PLUGIN_DATA_DIR; --no-cache disables it entirely.
739		CacheDir     string
740		DisableCache bool
741	}
742	
743	// idMatches reports whether a stable symbol ID matches a user-supplied selector:
744	// either the exact ID, or a trailing name segment (IDs end `...:kind:name`, so
745	// `getConfPath` or `function:getConfPath` both select it). Streaming-safe — no
746	// symbol table needed.
747	func idMatches(id, sel string) bool {
748		return id == sel || strings.HasSuffix(id, ":"+sel)
749	}
750	
751	// relationMatches applies the --to/--from/--relation predicate to one edge.
752	func relationMatches(r sem.RelationRecord, f providerFlags) bool {
753		if f.To != "" && !idMatches(r.ToID, f.To) {
754			return false
755		}
756		if f.From != "" && !idMatches(r.FromID, f.From) {
757			return false
758		}
759		if len(f.Relation) > 0 {
760			t := strings.ToUpper(r.Type)
761			hit := false
762			for _, want := range f.Relation {
763				if t == want {
764					hit = true
765					break
766				}
767			}
768			if !hit {
769				return false
770			}
771		}
772		return true
773	}
