867	func parseCommonFlags(args []string) (commonFlags, []string, error) {
868		flags := commonFlags{MaxSeconds: -1}
869		var rest []string
870		for i := 0; i < len(args); i++ {
871			arg := args[i]
872			switch arg {
873			case "--json":
874				flags.JSON = true
875			case "--progress":
876				flags.Progress = true
877			case "--max-seconds":
878				i++
879				if i >= len(args) {
880					return flags, nil, errors.New("--max-seconds requires a value")
881				}
882				seconds, err := strconv.Atoi(args[i])
883				if err != nil || seconds < 0 {
884					return flags, nil, fmt.Errorf("--max-seconds requires a non-negative integer, got %q", args[i])
885				}
886				flags.MaxSeconds = seconds
887			case "--repo":
888				i++
889				if i >= len(args) {
890					return flags, nil, errors.New("--repo requires a value")
891				}
892				flags.Repo = args[i]
893			case "--":
894				rest = append(rest, args[i+1:]...)
895				return flags, rest, nil
896			default:
897				rest = append(rest, arg)
898			}
899		}
900		return flags, rest, nil
901	}
