903	func runCommit(ctx context.Context, opts Options, args []string) error {
904		flags, rest, err := parseCommonFlags(args)
905		if err != nil {
906			return err
907		}
908		rev := "HEAD"
909		if len(rest) > 0 {
910			rev = rest[0]
911		}
912		if len(rest) > 1 {
913			return errors.New("commit accepts at most one revision")
914		}
915		if err := validateRevision("commit", rev); err != nil {
916			return err
917		}
918		repo, err := resolveRepo(ctx, opts.Env, flags.Repo)
919		if err != nil {
920			return err
921		}
922		if err := requireRangeRepoRoot(ctx, repo, "commit"); err != nil {
923			return err
924		}
925		base, err := gitutil.FirstParent(ctx, repo, rev)
926		if err != nil {
927			return err
928		}
929		return analyzeAndPrint(ctx, opts, repo, base, rev, nil, flags)
930	}
