963	
964	// validateRevision rejects a revision value that Git would read as an option instead.
965	//
966	// Every revision this package accepts is eventually spliced into a git argv — `git diff -z
967	// --raw --find-renames <base> <head> --` in gitutil.ChangedFiles, `git rev-parse
968	// <rev>^` in gitutil.FirstParent, `git show <rev>^{tree}:<path>` in gitutil.ShowFile. Git
969	// parses options anywhere ahead of `--`, so a value beginning with '-' stops being a revision
970	// and becomes a flag of the command it lands in: `diff --base '--output=FILE'` exited 0 having
971	// truncated FILE and replaced it with git's own name-status output (CWE-88), and `commit
972	// '--output=FILE'` reached the same argv because `git rev-parse '--output=FILE^'` does not
973	// fail first.
974	//
975	// Refusing at the boundary costs nothing legitimate. Values beginning with "--" are always
976	// Git options; bare "-" is ambiguous with git's path/option syntax. Single-hyphen refs such as
977	// "-foo" are valid and must not be rejected here — gitutil uses "--end-of-options" elsewhere
978	// when splicing user paths into git argv.
979	func validateRevision(name, rev string) error {
980		if rev == "" {
981			return fmt.Errorf("%s requires a revision", name)
982		}
983		if strings.HasPrefix(rev, "--") {
984			return fmt.Errorf("%s %q is not a revision: a revision cannot begin with %q, which Git would read as an option", name, rev, "--")
985		}
986		if rev == "-" {
987			return fmt.Errorf("%s %q is not a revision: bare %q is ambiguous with git's path/option syntax", name, rev, "-")
988		}
989		if strings.ContainsRune(rev, '\x00') {
990			return fmt.Errorf("%s %q is not a revision: a revision cannot contain a NUL byte", name, rev)
991		}
992		return nil
993	}
