995	// diffFlags is the parsed argument set for `diff` and its `analyze` alias.
996	type diffFlags struct {
997		common commonFlags
998		base   string
999		head   string
1000		paths  []string
1001	}
1002	
1003	// parseDiffFlags parses `diff`/`analyze` arguments, returning any flag-shaped argument it does
1004	// not recognize separately from the path filters, so the caller can reject it the way every
1005	// other verb does.
1006	//
1007	// Separating the two is the point. The parsing used to live inline in runDiff, whose default
1008	// branch filed EVERY unrecognized token under paths — so `diff --jsonn` exited 0 having filtered
1009	// the diff to a path that does not exist, and printed "No semantic entity changes detected". A
1010	// mistyped flag was answered with a confident empty result, which for a verb whose whole job is
1011	// telling you what changed is the worst possible way to be wrong.
1012	//
1013	// Paths that genuinely look like flags still work: that is what the documented `-- path...`
1014	// separator is for.
1015	// diffValueFlags are the `diff`/`analyze` flags whose value is the NEXT argument: the two
1016	// parseCommonFlags consumes and the two the loop below does. It exists only for the separator scan
1017	// above, which runs before either parser and so cannot ask them.
1018	var diffValueFlags = map[string]bool{
1019		"--repo":        true,
1020		"--max-seconds": true,
1021		"--base":        true,
1022		"--head":        true,
1023	}
1024	
1025	func parseDiffFlags(args []string) (diffFlags, []string, error) {
1026		parsed := diffFlags{base: "HEAD~1", head: "HEAD"}
1027	
1028		// Split on `--` here rather than letting parseCommonFlags consume it: that function flattens
1029		// everything after the separator into rest, which would leave a literal path named `--base`
1030		// indistinguishable from the real flag.
1031		//
1032		// Skipping each value-taking flag's value is what keeps `--` a separator rather than a pattern:
1033		// `diff --repo --` addresses a repository directory literally named `--`, and a raw scan cut the
1034		// arguments off in front of it and failed with "--repo requires a value" — with no `--repo=--`
1035		// spelling to fall back on, because these parsers accept no `=` form.
1036		flagArgs, literalPaths := args, []string(nil)
1037		for i := 0; i < len(args); i++ {
1038			if diffValueFlags[args[i]] {
1039				i++
1040				continue
1041			}
1042			if args[i] == "--" {
1043				flagArgs, literalPaths = args[:i], args[i+1:]
1044				break
1045			}
1046		}
1047	
1048		common, rest, err := parseCommonFlags(flagArgs)
1049		if err != nil {
1050			return diffFlags{}, nil, err
