1151	// filesystem fallback. Git canonicalizes entries before the first empty list
1152	// element, while an empty element promises that subsequent entries contain no
1153	// symlinks and can stay lexical. Canonicalization uses the provider's guarded
1154	// same-volume walk, which refuses off-volume and UNC redirects before probing
1155	// them. Unresolvable entries are discarded just as Git discards them.
1156	func discoverImplicitCheckoutRoot(dir string) (string, bool) {
1157		abs, err := filepath.Abs(dir)
1158		if err != nil {
1159			return "", false
1160		}
1161		abs = filepath.Clean(abs)
1162	
1163		type ceilingEntry struct {
1164			path         string
1165			canonicalize bool
1166		}
1167		var entries []ceilingEntry
1168		canonicalize := true
1169		for _, entry := range strings.Split(os.Getenv("GIT_CEILING_DIRECTORIES"), string(os.PathListSeparator)) {
1170			// Git documents ceiling entries as absolute paths. The first empty
1171			// entry disables canonicalization for every subsequent entry.
1172			if entry == "" {
1173				canonicalize = false
1174				continue
1175			}
1176			absoluteEntry, absolute := sem.GitAbsolutePath(abs, entry)
1177			if !absolute {
1178				if sem.GitAbsolutePathNeedsFailClosed(entry) {
1179					return "", false
1180				}
1181				continue
1182			}
1183			entries = append(entries, ceilingEntry{path: filepath.Clean(absoluteEntry), canonicalize: canonicalize})
1184		}
1185		if len(entries) == 0 {
1186			return discoverCheckoutRoot(dir)
1187		}
1188	
1189		resolver, resolution := sem.NewGitCeilingPathResolver(abs)
1190		if resolution != sem.GitCeilingPathResolved {
1191			if resolution != sem.GitCeilingPathUnsupported {
1192				return "", false
1193			}
1194			// Platforms without a safe mount inventory retain the prior lexical
1195			// behavior only when the caller put every usable entry after the
1196			// empty marker and therefore promised that none needs resolution.
1197			var ceilings []string
1198			for _, entry := range entries {
1199				if entry.canonicalize {
1200					return "", false
1201				}
1202				ceilings = append(ceilings, entry.path)
1203			}
1204			return discoverImplicitCheckoutRootBelowCeilings(abs, abs, ceilings, nil)
1205		}
1206		defer resolver.Close()
1207	
1208		physicalAbs, resolution := resolver.Canonicalize(abs)
1209		if resolution != sem.GitCeilingPathResolved {
1210			return "", false
1211		}
1212		ceilings := make([]string, 0, len(entries))
1213		for _, entry := range entries {
1214			ceiling := entry.path
1215			if entry.canonicalize {
1216				resolved, resolution := resolver.Canonicalize(ceiling)
