1224					// learn whether it aliases an ancestor. Refuse implicit
1225					// discovery rather than risk either network I/O or walking
1226					// through a boundary whose canonical spelling is unknown.
1227					return "", false
1228				}
1229			}
1230			ceilings = append(ceilings, ceiling)
1231		}
1232		return discoverImplicitCheckoutRootBelowCeilings(abs, physicalAbs, ceilings, resolver)
1233	}
