1235	func discoverImplicitCheckoutRootBelowCeilings(namedStart, physicalStart string, ceilings []string, resolver *sem.GitCeilingPathResolver) (string, bool) {
1236		applicable := ceilings[:0]
1237		for _, ceiling := range ceilings {
1238			rel, err := filepath.Rel(ceiling, physicalStart)
1239			if err == nil && rel != "." && rel != ".." && !strings.HasPrefix(rel, ".."+string(filepath.Separator)) && !filepath.IsAbs(rel) {
1240				applicable = append(applicable, ceiling)
1241			}
1242		}
1243		abs := physicalStart
1244		for {
1245			for _, ceiling := range applicable {
1246				equal := abs == ceiling
1247				if runtime.GOOS == "windows" {
1248					equal = strings.EqualFold(abs, ceiling)
1249				}
1250				if equal {
1251					return "", false
1252				}
1253			}
1254			if resolver == nil {
1255				if _, err := os.Lstat(filepath.Join(abs, ".git")); err == nil {
1256					return abs, true
1257				}
1258			} else {
1259				exists, resolution := resolver.HasGitEntry(abs)
1260				if resolution != sem.GitCeilingPathResolved {
1261					return "", false
1262				}
1263				if exists {
1264					return preferredCheckoutRootSpelling(resolver, namedStart, abs)
1265				}
1266			}
1267			parent := filepath.Dir(abs)
1268			if parent == abs {
1269				return "", false
1270			}
1271			abs = parent
1272		}
1273	}
