1275	// preferredCheckoutRootSpelling preserves the caller-visible spelling used by
1276	// the filesystem fallback when it names the physical checkout Git discovery
1277	// found. This matters on systems such as macOS where /var is an alias for
1278	// /private/var: ceilings must be compared physically, but an unrelated ceiling
1279	// must not silently change the checkout path returned to existing callers.
1280	func preferredCheckoutRootSpelling(resolver *sem.GitCeilingPathResolver, namedStart, physicalRoot string) (string, bool) {
1281		for candidate := namedStart; ; candidate = filepath.Dir(candidate) {
1282			resolved, resolution := resolver.Canonicalize(candidate)
1283			if resolution == sem.GitCeilingPathUnsafe {
1284				return "", false
1285			}
1286			equal := resolved == physicalRoot
1287			if runtime.GOOS == "windows" {
1288				equal = strings.EqualFold(resolved, physicalRoot)
1289			}
1290			if resolution == sem.GitCeilingPathResolved && equal {
1291				return candidate, true
1292			}
1293			parent := filepath.Dir(candidate)
1294			if parent == candidate {
1295				return physicalRoot, true
1296			}
1297		}
1298	}
