1300	func analyzeAndPrint(ctx context.Context, opts Options, repo, base, head string, paths []string, flags commonFlags) error {
1301		maxSeconds := flags.MaxSeconds
1302		if maxSeconds < 0 {
1303			maxSeconds = defaultMaxSeconds
1304		}
