1306			MaxDuration: time.Duration(maxSeconds) * time.Second,
1307		}
1308		if flags.Progress {
1309			analyzeOptions.Progress = func(event sem.AnalyzeProgressEvent) {
1310				fmt.Fprintln(opts.Stderr, diffProgressLine(event))
1311			}
1312		}
