1320	// diffProgressLine renders one --progress event for stderr.
1321	//
1322	// It is a named function rather than an inline closure because of the escaping:
1323	// event.Path is a raw Git pathname carried through from `git diff -z`, which may
1324	// hold any byte but NUL and '/', and this is the one sink that has to escape by
1325	// value instead of by wrapping its writer — stderr also carries the progress
1326	// bar's own cursor control (see progressbar.go), which a wrap could not tell
1327	// apart from an injected sequence.
1328	func diffProgressLine(event sem.AnalyzeProgressEvent) string {
1329		line := fmt.Sprintf("graph diff progress phase=%s files=%d/%d elapsed=%s",
1330			event.Phase,
1331			event.FilesDone,
1332			event.FilesTotal,
1333			event.Elapsed.Round(time.Millisecond),
1334		)
1335		if event.Path != "" {
1336			line += " file=" + termsafe.Line(event.Path)
1337		}
1338		return line
1339	}
