1341	func printResult(out io.Writer, result sem.Result, asJSON bool, producerVersion string) error {
1342		// ProducerVersion is set here, the one place a Result is rendered, rather
1343		// than at each of the two callers — it needs the CLI's build-time version
1344		// (Options.Version), which the sem package that builds the rest of the
1345		// Result has no access to.
1346		result.ProducerVersion = producerVersion
1347		if asJSON {
1348			encoded, err := json.MarshalIndent(result, "", "  ")
1349			if err != nil {
1350				return err
1351			}
1352			fmt.Fprintln(termsafe.NewJSONWriter(out), string(encoded))
1353			return nil
1354		}
1355		sem.WriteText(out, result)
1356		return nil
1357	}
