}

// NewRendererWith builds a renderer with an explicit theme and capabilities.
func NewRendererWith(theme Theme, caps Caps) *Renderer {
	return &Renderer{theme: theme, caps: caps}
}

// Caps reports what this renderer's destination can render.
func (r *Renderer) Caps() Caps {
	if r == nil {
		return PlainCaps()
	}
	return r.caps
}

// Theme reports the palette in use.
// coloured one.
func (r *Renderer) MarkGlyph(m Mark) string {
	glyph, _ := r.markGlyph(m)
	return glyph
}

func (r *Renderer) markGlyph(m Mark) (string, lipgloss.Color) {
	theme := r.Theme()
	unicode := r != nil && r.caps.Unicode
	switch m {
	case MarkDone:
		if unicode {
			return "✓", theme.Good
		}
		return "+", theme.Good
	case MarkFailed:
		if unicode {
			return "✗", theme.Bad
		}
		return "x", theme.Bad
	case MarkSkipped:
		if unicode {
			return "−", theme.Dim
		}
		return "-", theme.Dim
	default:
		if unicode {
			return "·", theme.Dim
		}
		return ".", theme.Dim
	}
}

